43.     byte[] decodedBytes = Base64.getDecoder().decode(base64);
44.     return new String(decodedBytes, StandardCharsets.UTF_8);
45.   }
46. 
47.   private String calculateHash(String hash, String input) {
48.     try {
49.       if (md5Hash.equals(hash) || sha1Hash.equals(hash)) {
50.         var md = MessageDigest.getInstance(hash);
51.         return new String(Hex.encode(md.digest(input.getBytes(StandardCharsets.UTF_8))));
52.       }
53.     } catch (NoSuchAlgorithmException e) {
54.       log.warn("Exception thrown when calculating hash", e);
55.     }
56.     return "No Hash Selected";
