68.     return calculateHash(md5Hash, base64Decode(hashPassword)).equals(calculateHash(md5Hash, answer))
69.         || calculateHash(sha1Hash, base64Decode(hashPassword))
70.             .equals(calculateHash(sha1Hash, answer));
71.   }
72. 
